nM(a){return"\uc5b8\uc5b4 \ubaa8\ub378 \ud63c\ub780\ub3c4\uac00 \uc911\uac04 \uc218\uc900\uc785\ub2c8\ub2e4\uff08"+a+"\uff09"},
