gm4(){return"\uac1c\uc778\uc815\ubcf4\ucc98\ub9ac\ubc29\uce68"},
qz(a){return"\ucd5c\uc885 \uc5c5\ub370\uc774\ud2b8: "+a},
gqM(){return"TruthLens\ub294 \ube0c\ub77c\uc6b0\uc800 \ud0ed\uc5d0\uc11c \uc644\uc804\ud788 \uc6f9 \uc571\uc73c\ub85c \uc2e4\ud589\ub429\ub2c8\ub2e4. \uc124\uce58\ud560 \ud544\uc694\uac00 \uc5c6\uc73c\uba70, \ubb38\uc11c \ud14d\uc2a4\ud2b8\uc640 \ubd84\uc11d \uacb0\uacfc\ub294 \uae30\uae30\ub97c \ubc97\uc5b4\ub098\uc9c0 \uc54a\uace0, \ub2e4\uc6b4\ub85c\ub4dc\ub41c \uac10\uc9c0 \ubaa8\ub378\uc740 \uc11c\ubc84\uac00 \uc544\ub2cc \ube0c\ub77c\uc6b0\uc800 \uc790\uccb4\uc758 \uc0cc\ub4dc\ubc15\uc2a4 \uc800\uc7a5\uc18c\uff08OPFS\uff09\uc5d0\ub9cc \uce90\uc2dc\ub429\ub2c8\ub2e4."},
gqN(){return"\uc774 \ud398\uc774\uc9c0\ub294 \uc0ac\uc6a9\uc790\uac00 \uc801\uadf9\uc801\uc73c\ub85c \uac00\uc838\uc624\uae30, \uc2a4\uce94 \ub610\ub294 \ubd99\uc5ec\ub123\uae30\ub97c \uc120\ud0dd\ud560 \ub54c\ub9cc \ud30c\uc77c, \uc774\ubbf8\uc9c0 \ub610\ub294 \ud074\ub9bd\ubcf4\ub4dc \ucf58\ud150\uce20\ub97c \uc77d\uc2b5\ub2c8\ub2e4. \ub2e4\ub978 \ud0ed, \ub2e4\ub978 \uc0ac\uc774\ud2b8\uc758 \ub370\uc774\ud130 \ub610\ub294 \uc120\ud0dd\ud558\uc9c0 \uc54a\uc740 \ud30c\uc77c\uc740 \uc808\ub300 \uc77d\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4."},
